INSERT INTO knowledge_entries (id, source_file, source_page, title, text_layer, kind, used_for, symptoms, how_to_give, schedule_text, precautions) VALUES
('330bee4e-85d7-5f65-a916-ab8ef1820b2b', 'patil-poultry-antibiotics.pdf', 1, 'Lixen powder', 'प्रामुख्याने ई. कोलाय (सफेद संडास), गँग्रीनस डर्माटायटीस (त्वचेचे रोग) आणि सांधेदुखी (Arthritis) यांसारख्या गंभीर आजारांवर हे वापरले जाते.

पावडर स्वरूपात येते. साधारण १ ग्रॅम पावडर २ ते ३ लिटर पाण्यात मिसळून, किंवा पक्षांच्या वयानुसार डॉक्टरांच्या सल्ल्याने, पाण्यातून दिली जाते.

संसर्गाची तीव्रता पाहून साधारण ३ ते ५ दिवस सलग दिले जाते.

डॉक्टरांच्या सल्ल्याने. मालक किंवा पशुवैद्य या पानाशी तपासूनच वापरावे. कार्यक्रम स्वतः डोस ठरवत नाही.', 'medicine', 'प्रामुख्याने ई. कोलाय (सफेद संडास), गँग्रीनस डर्माटायटीस (त्वचेचे रोग) आणि सांधेदुखी (Arthritis) यांसारख्या गंभीर आजारांवर हे वापरले जाते.', '', 'पावडर स्वरूपात येते. साधारण १ ग्रॅम पावडर २ ते ३ लिटर पाण्यात मिसळून, किंवा पक्षांच्या वयानुसार डॉक्टरांच्या सल्ल्याने, पाण्यातून दिली जाते.', 'संसर्गाची तीव्रता पाहून साधारण ३ ते ५ दिवस सलग दिले जाते.', 'डॉक्टरांच्या सल्ल्याने. मालक किंवा पशुवैद्य या पानाशी तपासूनच वापरावे. कार्यक्रम स्वतः डोस ठरवत नाही.'),
('75bb0fd9-7868-5daa-86a8-dc3899f44b45', 'patil-poultry-antibiotics.pdf', 2, 'Tetracycline powder', 'हे प्रामुख्याने मृत्यू कमी करण्यासाठी, कॉलरा, मानमोडी (Ranikhet) मधील दुय्यम संसर्ग आणि कोंबड्यांमधील ताण घालवण्यासाठी वापरले जाते.

पावडर स्वरूपात मिळते. साधारण १ ग्रॅम औषध २ ते ४ लिटर पाण्यात मिसळून, किंवा पक्षांच्या संख्येनुसार, पाण्यातून दिले जाते.

जेव्हा पक्षी दाणा-पाणी कमी करतात किंवा सुस्त होतात, तेव्हा साधारण ३ ते ५ दिवस सलग हे औषध दिले जाते.', 'medicine', 'हे प्रामुख्याने मृत्यू कमी करण्यासाठी, कॉलरा, मानमोडी (Ranikhet) मधील दुय्यम संसर्ग आणि कोंबड्यांमधील ताण घालवण्यासाठी वापरले जाते.', '', 'पावडर स्वरूपात मिळते. साधारण १ ग्रॅम औषध २ ते ४ लिटर पाण्यात मिसळून, किंवा पक्षांच्या संख्येनुसार, पाण्यातून दिले जाते.', 'जेव्हा पक्षी दाणा-पाणी कमी करतात किंवा सुस्त होतात, तेव्हा साधारण ३ ते ५ दिवस सलग हे औषध दिले जाते.', 'मालक किंवा पशुवैद्य या पानाशी तपासूनच वापरावे. कार्यक्रम स्वतः डोस ठरवत नाही.'),
('dc1c6761-f971-528f-8675-d7306b0e6321', 'patil-poultry-antibiotics.pdf', 3, 'Neodox forte powder', 'हे प्रामुख्याने सीआरडी (श्वसनाचे आजार) आणि ई. कोलाय (पोटातील संसर्ग) हे दोन्ही त्रास एकाच वेळी असल्यास वापरले जाते.

पावडर स्वरूपात असते. साधारण १ ग्रॅम औषध २ ते ४ लिटर पाण्यात मिसळून, किंवा पक्षांच्या वजनानुसार तज्ज्ञांच्या सल्ल्याने, दिले जाते.

कोंबड्यांमधील मृत्यू रोखण्यासाठी आणि आतड्यांमधील जंतू कमी करण्यासाठी हे ३ ते ५ दिवस सलग दिले जाते.', 'medicine', 'हे प्रामुख्याने सीआरडी (श्वसनाचे आजार) आणि ई. कोलाय (पोटातील संसर्ग) हे दोन्ही त्रास एकाच वेळी असल्यास वापरले जाते.', '', 'पावडर स्वरूपात असते. साधारण १ ग्रॅम औषध २ ते ४ लिटर पाण्यात मिसळून, किंवा पक्षांच्या वजनानुसार तज्ज्ञांच्या सल्ल्याने, दिले जाते.', 'कोंबड्यांमधील मृत्यू रोखण्यासाठी आणि आतड्यांमधील जंतू कमी करण्यासाठी हे ३ ते ५ दिवस सलग दिले जाते.', 'मालक किंवा पशुवैद्य या पानाशी तपासूनच वापरावे. कार्यक्रम स्वतः डोस ठरवत नाही.'),
('43a53591-3303-5625-a670-3ace46504a16', 'patil-poultry-antibiotics.pdf', 4, 'Enrocin BH liquid', 'हे प्रामुख्याने सीआरडी (खडखड आवाज) आणि फुफ्फुसातील दाट कफ काढून श्वसनाचा मार्ग मोकळा करण्यासाठी वापरले जाते.

द्रव स्वरूपात येते. साधारण १ मिली औषध २ ते ४ लिटर पाण्यात मिसळून सकाळी किंवा संध्याकाळी थंड वेळेत दिले जाते.

जेव्हा पक्षांना श्वास घ्यायला त्रास होतो किंवा मान वर करून श्वास घेतात, तेव्हा साधारण ३ ते ५ दिवस सलग हे औषध दिले जाते.', 'medicine', 'हे प्रामुख्याने सीआरडी (खडखड आवाज) आणि फुफ्फुसातील दाट कफ काढून श्वसनाचा मार्ग मोकळा करण्यासाठी वापरले जाते.', '', 'द्रव स्वरूपात येते. साधारण १ मिली औषध २ ते ४ लिटर पाण्यात मिसळून सकाळी किंवा संध्याकाळी थंड वेळेत दिले जाते.', 'जेव्हा पक्षांना श्वास घ्यायला त्रास होतो किंवा मान वर करून श्वास घेतात, तेव्हा साधारण ३ ते ५ दिवस सलग हे औषध दिले जाते.', 'मालक किंवा पशुवैद्य या पानाशी तपासूनच वापरावे. कार्यक्रम स्वतः डोस ठरवत नाही.'),
('3e9dc733-4743-5fbb-bac7-2d135bce04ac', 'patil-poultry-antibiotics.pdf', 5, 'Azithromycin tablet', 'Azithromycin tablet. या पानावर फक्त डबीचा फोटो आहे.', 'medicine', '', '', '', '', 'या पानावर फक्त गोळीची डबी दिसते. कशासाठी, किती आणि केव्हा हे या पानावर लिहिलेले नाही. मालक किंवा पशुवैद्य या पानाशी तपासूनच वापरावे. कार्यक्रम स्वतः डोस ठरवत नाही.'),
('0fdf9ad1-561a-5a2f-a81a-464a2774d942', 'patil-poultry-antibiotics.pdf', 6, 'Pharmasin 100%', 'Pharmasin 100%. या पानावर फक्त डबीचा फोटो आहे.', 'medicine', '', '', '', '', 'या पानावर फक्त डबी दिसते. कशासाठी, किती आणि केव्हा हे या पानावर लिहिलेले नाही. मालक किंवा पशुवैद्य या पानाशी तपासूनच वापरावे. कार्यक्रम स्वतः डोस ठरवत नाही.'),
('bcda0463-deb2-50e0-8168-29ce088cf5fc', 'patil-poultry-antibiotics.pdf', 7, 'Trox', 'प्रामुख्याने सीआरडी (खडखड आवाज), सर्दी, घशात कफ होणे आणि डोळ्यातून पाणी येणे यांवर हे वापरले जाते.

पावडर स्वरूपात येते. साधारण १ ग्रॅम औषध १ ते २ लिटर पाण्यात मिसळून कोंबड्यांना सकाळी पिण्यासाठी दिले जाते.

हे औषध साधारण ३ ते ५ दिवस सतत दिले जाते.', 'medicine', 'प्रामुख्याने सीआरडी (खडखड आवाज), सर्दी, घशात कफ होणे आणि डोळ्यातून पाणी येणे यांवर हे वापरले जाते.', '', 'पावडर स्वरूपात येते. साधारण १ ग्रॅम औषध १ ते २ लिटर पाण्यात मिसळून कोंबड्यांना सकाळी पिण्यासाठी दिले जाते.', 'हे औषध साधारण ३ ते ५ दिवस सतत दिले जाते.', 'मालक किंवा पशुवैद्य या पानाशी तपासूनच वापरावे. कार्यक्रम स्वतः डोस ठरवत नाही.'),
('4899d057-c795-5c08-8406-e028f995cd25', 'patil-poultry-antibiotics.pdf', 8, 'Supercox / Amprolium', 'हे प्रामुख्याने कॉक्सिडिओसिस, म्हणजे रक्ती हगवण (संडासवाटे रक्त पडणे), या आजारावर वापरले जाते.

पावडर स्वरूपात येते. साधारण १ ते २ ग्रॅम पावडर १ ते २ लिटर पाण्यात मिसळून, किंवा डॉक्टरांच्या सल्ल्यानुसार, पिण्याच्या पाण्यातून दिले जाते.

जेव्हा पक्षी रक्तमिश्रित किंवा विटकरी रंगाची संडास करतात, तेव्हा संसर्गाची तीव्रता पाहून साधारण ३ ते ५ दिवस सलग हे औषध दिले जाते.', 'medicine', 'हे प्रामुख्याने कॉक्सिडिओसिस, म्हणजे रक्ती हगवण (संडासवाटे रक्त पडणे), या आजारावर वापरले जाते.', '', 'पावडर स्वरूपात येते. साधारण १ ते २ ग्रॅम पावडर १ ते २ लिटर पाण्यात मिसळून, किंवा डॉक्टरांच्या सल्ल्यानुसार, पिण्याच्या पाण्यातून दिले जाते.', 'जेव्हा पक्षी रक्तमिश्रित किंवा विटकरी रंगाची संडास करतात, तेव्हा संसर्गाची तीव्रता पाहून साधारण ३ ते ५ दिवस सलग हे औषध दिले जाते.', 'मालक किंवा पशुवैद्य या पानाशी तपासूनच वापरावे. कार्यक्रम स्वतः डोस ठरवत नाही.'),
('05bc4779-00de-5583-97d3-8d9d6f4f5cab', 'patil-poultry-antibiotics.pdf', 9, 'Brotone liver tonic', 'हे प्रामुख्याने यकृत सांभाळण्यासाठी, पचनशक्ती वाढवण्यासाठी आणि पक्षांची भूक वाढवण्यासाठी वापरले जाते.

द्रव स्वरूपात येते. साधारण १० ते २० मिली औषध १०० पक्षांसाठी पिण्याच्या पाण्यातून दिले जाते.

जेव्हा पक्षी दाणा कमी खातात, वाढ खुंटते, किंवा प्रतिजैविक चालू असते, तेव्हा दिले जाते. ५ ते ७ दिवस.', 'medicine', 'हे प्रामुख्याने यकृत सांभाळण्यासाठी, पचनशक्ती वाढवण्यासाठी आणि पक्षांची भूक वाढवण्यासाठी वापरले जाते.', '', 'द्रव स्वरूपात येते. साधारण १० ते २० मिली औषध १०० पक्षांसाठी पिण्याच्या पाण्यातून दिले जाते.', 'जेव्हा पक्षी दाणा कमी खातात, वाढ खुंटते, किंवा प्रतिजैविक चालू असते, तेव्हा दिले जाते. ५ ते ७ दिवस.', 'मालक किंवा पशुवैद्य या पानाशी तपासूनच वापरावे. कार्यक्रम स्वतः डोस ठरवत नाही.'),
('72b70902-44e4-5912-a8d6-f12f047333a9', 'patil-poultry-antibiotics.pdf', 10, 'Calgophos / Ostovet forte', 'Calgophos / Ostovet forte. या पानावर फक्त डबीचा फोटो आहे.', 'medicine', '', '', '', '', 'या पानावर फक्त डबी दिसते. कशासाठी, किती आणि केव्हा हे या पानावर लिहिलेले नाही. मालक किंवा पशुवैद्य या पानाशी तपासूनच वापरावे. कार्यक्रम स्वतः डोस ठरवत नाही.'),
('65ad9538-0b67-59de-a48b-cf63134b4a4a', 'patil-poultry-antibiotics.pdf', 11, 'Neurobin forte tablet', 'हे प्रामुख्याने लंगडेपणा, पाय कमजोर होणे, मान फिरणे आणि नसांच्या कमकुवतपणावर वापरले जाते.

गोळ्यांच्या स्वरूपात येते. १०० पक्षांसाठी २ ते ३ गोळ्या बारीक करून पाण्यातून किंवा दाण्यातून दिल्या जातात.

जेव्हा पक्षी पाय ओढून चालतात किंवा नीट उभे राहत नाहीत, तेव्हा साधारण ५ ते ७ दिवस दिले जाते.', 'medicine', 'हे प्रामुख्याने लंगडेपणा, पाय कमजोर होणे, मान फिरणे आणि नसांच्या कमकुवतपणावर वापरले जाते.', '', 'गोळ्यांच्या स्वरूपात येते. १०० पक्षांसाठी २ ते ३ गोळ्या बारीक करून पाण्यातून किंवा दाण्यातून दिल्या जातात.', 'जेव्हा पक्षी पाय ओढून चालतात किंवा नीट उभे राहत नाहीत, तेव्हा साधारण ५ ते ७ दिवस दिले जाते.', 'मालक किंवा पशुवैद्य या पानाशी तपासूनच वापरावे. कार्यक्रम स्वतः डोस ठरवत नाही.'),
('1c5ef057-afa7-53d8-b5be-7dabc64c02e9', 'patil-poultry-antibiotics.pdf', 12, 'Groviplex', 'प्रामुख्याने पक्षांची भूक वाढवण्यासाठी, वाढीसाठी आणि शरीरातील जीवनसत्त्वांची कमतरता भरून काढण्यासाठी हे वापरले जाते.

द्रव स्वरूपात येते. साधारण १५ ते २० मिली औषध १०० पक्षांसाठी पिण्याच्या पाण्यातून दिले जाते.

